{
  "name": "通用Modbus TCP工业设备",
  "name_en": "Generic Modbus TCP Industrial Device",
  "manufacturer": "",
  "description": "这是一类通过 Modbus TCP 通信的工业现场设备，例如温控器、PLC、远程 I/O 模块或电力仪表。它们常用于实验室和测试系统中读取线圈与寄存器数据，并向设备写入开关量或参数设定，实现状态监测、数据采集和过程控制。",
  "description_en": "This refers to industrial field devices that communicate over Modbus TCP, such as temperature controllers, PLCs, remote I/O modules, or power meters. In laboratories and test systems, they are commonly used to read coils and registers and to write switching signals or parameter values for monitoring, data acquisition, and process control.",
  "tag_hints": [
    "Modbus TCP",
    "industrial control",
    "PLC communication",
    "remote I/O",
    "register readout",
    "coil control"
  ],
  "actions": [
    {
      "action_name": "auto-read_coils",
      "description": "读取设备的 Modbus 线圈状态。",
      "description_en": "Read the device's Modbus coil states."
    },
    {
      "action_name": "auto-read_holding_registers",
      "description": "读取设备的 Modbus 保持寄存器。",
      "description_en": "Read the device's Modbus holding registers."
    },
    {
      "action_name": "auto-read_registers",
      "description": "读取设备的 Modbus 寄存器。",
      "description_en": "Read the device's Modbus registers."
    },
    {
      "action_name": "auto-write_coil",
      "description": "写入设备的单个 Modbus 线圈。",
      "description_en": "Write a single Modbus coil on the device."
    },
    {
      "action_name": "auto-write_coils",
      "description": "写入设备的多个 Modbus 线圈。",
      "description_en": "Write multiple Modbus coils on the device."
    },
    {
      "action_name": "auto-write_register",
      "description": "写入设备的单个 Modbus 寄存器。",
      "description_en": "Write a single Modbus register on the device."
    },
    {
      "action_name": "auto-write_registers",
      "description": "写入设备的多个 Modbus 寄存器。",
      "description_en": "Write multiple Modbus registers on the device."
    }
  ]
}

